import { logger } from '../../logger'
import { initOAuthFlow, oAuthClient } from './CodeGrant'

export type OAuthTokenSet = {
    access_token: string
    token_type: string
    refresh_token: string
    expires_at: number
}

export const getOAuthTokens = async (host: string): Promise<OAuthTokenSet | undefined> => {
    try {
        // initialize the oauth flow and wait for the user to authorize the app
        const token = await initOAuthFlow(host)
        if (token) {
            return {
                access_token: token.access_token!,
                token_type: token.token_type!,
                refresh_token: token.refresh_token!,
                expires_at: token.expires_at!,
            }
        }

        return
    } catch (error: any) {
        logger.error('Access Token Error', error)
        return
    }
}

export async function refreshAccessToken(creds: {
    instanceUrl: string
    refresh_token: string
    expires_at: number
}): Promise<OAuthTokenSet | undefined> {
    const { instanceUrl, refresh_token, expires_at } = creds
    const now = Math.floor(Date.now() / 1000)
    const expiresIn = expires_at - now

    const client = await oAuthClient(instanceUrl)
    // check if the token is about to expire in 10 minutes
    if (expiresIn > 15 * 60) {
        return
    }
    logger.info('Access Token has expired, refreshing token')
    try {
        const token = await client.refresh(refresh_token)
        // get the access token from the store

        return {
            access_token: token.access_token!,
            token_type: token.token_type!,
            refresh_token: token.refresh_token!,
            expires_at: token.expires_at!,
        }
    } catch (error) {
        const msg = error instanceof Error ? error.message : String(error)
        throw new Error(
            `Error refreshing token: ${msg}. Use "now-sdk auth --add <instance>" command to initiate OAuth and retrieve new access/refresh tokens`,
            { cause: error }
        )
    }
}
